// Photo asset "air-purifier" — added by the builder (their own real, local image).
// Use it in any page with:
//   <script src="./assets/air-purifier.js"></script>
//   <img data-asset="air-purifier" alt="describe the photo">
window.ASSETS = Object.assign(window.ASSETS || {}, { "air-purifier": "data:image/jpeg;base64," });
(function () {
  function apply() { document.querySelectorAll('img[data-asset="air-purifier"]').forEach(function (img) { img.src = window.ASSETS["air-purifier"]; }); }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', apply); else apply();
})();
